import sqlite3
import json
import sys
from pathlib import Path

def generate_html_report(db_path, filters):
    with open('filters.json', 'r') as f:
        json_filters = json.load(f)

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    # Get all columns to filter on
    filter_columns = set(json_filters.keys())
    all_columns = ['id', 'name', 'email', 'status', 'city']
    columns_to_query = list(filter_columns.union(set(all_columns)))

    # Build WHERE clause dynamically
    where_clause_parts = []
    params = []
    for col, val in json_filters.items():
        where_clause_parts.append(f"{col} = ?")
        params.append(val)

    where_clause = " AND ".join(where_clause_parts) if where_clause_parts else ""
    query = f"SELECT {', '.join(columns_to_query)} FROM people WHERE {where_clause} ORDER BY id"

    cursor.execute(query, params)
    rows = cursor.fetchall()

    conn.close()

    # Generate HTML
    filter_str = ", ".join([f"{k}={v}" for k, v in json_filters.items()])
    html = f"""<!DOCTYPE html>
<html>
<head>
    <title>People Report</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }}
        th {{
            background-color: #f2f2f2;
        }}
    </style>
</head>
<body>
    <h1>People Report</h1>
    <p>Filters: {filter_str}</p>
    <table>
        <tr>
            <th>id</th>
            <th>name</th>
            <th>email</th>
            <th>status</th>
            <th>city</th>
        </tr>
    {'' if not rows else ''}
    {''.join([f'<tr><td>{row[0]}</td><td>{row[1]}</td><td>{row[2]}</td><td>{row[3]}</td><td>{row[4]}</td></tr>' for row in rows])}
    </table>
</body>
</html>"""

    with open('report.html', 'w') as f:
        f.write(html)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python report.py <database_path>", file=sys.stderr)
        sys.exit(1)

    db_path = sys.argv[1]
    generate_html_report(db_path, {})
